{
  "items": [
    {
      "label": "FIGURE O.14",
      "kind": "chart",
      "title": "Rates of multidimensional poverty and increased risks from extreme weather in IDA countries compared with other countries",
      "bbox": [
        288,
        165,
        655,
        835
      ],
      "content": {
        "panel_a": {
          "title": "a. Deprivation rates in dimensions of multidimensional poverty (circa 2021)",
          "type": "horizontal bar chart",
          "axis_x": "Deprivation rate (%)",
          "axis_y": ["Drinking water", "Sanitation", "Electricity", "Educational enrollment", "Educational attainment", "Monetary"],
          "legend": ["IDA*", "FCS*", "Sub-Saharan Africa*", "World*"],
          "data_trends": "IDA* consistently shows the highest deprivation rates across all categories, followed by FCS* and Sub-Saharan Africa*. World* shows the lowest deprivation rates."
        },
        "panel_b": {
          "title": "b. Change in exposure to and risk from extreme weather events in IDA and non-IDA",
          "type": "bar chart",
          "axis_x": ["Exposed (IDA)", "At risk (IDA)", "Exposed (Non-IDA)", "At risk (Non-IDA)"],
          "axis_y": "Change in population between 2010 and 2019 (%)",
          "data_values": {
            "IDA_Exposed": "approx. 21%",
            "IDA_At_risk": "approx. 17%",
            "Non-IDA_Exposed": "approx. 10%",
            "Non-IDA_At_risk": "approx. -15%"
          }
        },
        "sources": "Panel a: World Bank calculations using data from the Global Monitoring Database. Panel b: World Bank calculations using data from Doan et al. 2023.",
        "notes": "FCS = fragile and conflict-affected situations; IDA = International Development Association. Panel a: The figure presents the share of population deprived in each indicator of the multidimensional poverty measure for selected regions and country groupings circa 2021. For more information on the multidimensional poverty measure and its components, see chapter 1 of the full report. Panel b: The sample consists of 45 countries that have data both for 2010 and 2019. These countries represent 52 percent of the population in IDA and 63 percent of the population in non-IDA countries. The variables used to compute the risk indicator for the years 2010 and 2019 differ slightly from the risk indicator for the year 2021 used in other parts of the report. *The surveys available for 2020 or later cover less than 50 percent of the population."
      }
    }
  ]
}
